"""Spectral theory, quadratic forms, positive definiteness, and the SVD."""
from nodespec import N

N("self_adjoint", "definition", "spectral",
  "T is self-adjoint (Hermitian) if T = T^*; over R this reads A = A^T (symmetric). Equivalently <Tv,w> = <v,Tw> for all v, w, and over C equivalently <Tv,v> is REAL for every v.",
  parseable="T = T^*;  over R: A^T = A;  <Tv,w> = <v,Tw>;  over C: <Tv,v> in R for all v",
  symbols={"T^*": "the adjoint"},
  tcn="Well-formed for an OPERATOR (T^* has the same domain and codomain only then). The 'real quadratic form' characterisation is a COMPLEX phenomenon: over R, <Tv,v> is automatically real for every T, so that criterion is vacuous there.",
  hyps=["T in L(V)", "V an inner product space"],
  field_scope="real_or_complex",
  proof=("the equivalences from the defining property of the adjoint; the complex real-form criterion by polarisation", "adjoint_operator", "core", "LinAlg.selfadjoint_iff_sym (2x2 Int instance)"),
  spec=["orthogonal projections are self-adjoint (projection_matrix_characterisation)",
        "covariance matrices and Gram matrices are real symmetric",
        "a real DIAGONAL matrix is self-adjoint"],
  cxd={"the_complex_criterion_is_complex_only": "over R, <Av,v> is real for EVERY A, so it cannot detect symmetry. Indeed [[0,-1],[1,0]] has <Av,v> = 0 for all v and is not symmetric. Over C the criterion is genuinely equivalent -- an asymmetry worth remembering",
       "complex_symmetric_is_not_Hermitian": "A^T = A over C is a different, badly behaved class: [[1,i],[i,-1]] is complex symmetric, has p(t) = t^2, and is NILPOTENT -- nothing like a Hermitian matrix"},
  misuse=["defining Hermitian as A^T = A over C",
          "using the 'real quadratic form' test over R, where it is vacuous"],
  related={"required_by": ["spectral_theorem_symmetric", "positive_definite", "normal_matrix", "rayleigh_quotient"]},
  sources=["axler_lada_4e", "horn_johnson_2e"], status="reviewed")

N("orthogonal_matrix", "definition", "spectral",
  "Q in R^{n x n} is orthogonal if Q^TQ = QQ^T = I; U in C^{n x n} is unitary if U^*U = I. Equivalently the columns (and rows) are orthonormal, Q^{-1} = Q^T, and |det Q| = 1. The orthogonal matrices form a group O(n).",
  parseable="Q^TQ = I  <=>  columns orthonormal  <=>  Q^{-1} = Q^T;  det Q = +-1;  O(n) a group",
  symbols={"Q": "orthogonal", "U": "unitary", "O(n), U(n)": "the orthogonal and unitary groups"},
  tcn="Well-formed for SQUARE matrices, where Q^TQ = I and QQ^T = I are equivalent by one_sided_inverse_square. For rectangular Q with m > n only Q^TQ = I can hold -- QQ^T is then a rank-n projection, NOT the identity, which is exactly the reduced-QR situation.",
  hyps=["Q square for the two-sided identity"],
  field_scope="real_or_complex",
  proof=("Q^TQ = I says the (i,j) entry is <q_i, q_j> = delta_{ij}; the group property from (QR)^T(QR) = R^TQ^TQR = I", "orthonormal_basis", "core", "LinAlg.orthogonal_iff_cols_orthonormal (2x2 Int instance)"),
  spec=["rotations and reflections in R^2; det = +1 for rotations, -1 for reflections",
        "permutation matrices are orthogonal",
        "the Q of a QR factorisation has orthonormal COLUMNS but is generally rectangular, so QQ^T is a projection"],
  cxd={"squareness": "for Q in R^{m x n} with m > n and Q^TQ = I, QQ^T is the projection onto col(Q), not I. Treating a reduced-QR Q as 'orthogonal' in the two-sided sense is a standard error",
       "det_pm_one_is_not_sufficient": "det = +-1 does NOT imply orthogonal: [[1,1],[0,1]] has det 1 and is not orthogonal. Orthogonality is a much stronger, metric condition"},
  misuse=["inferring orthogonality from det = 1",
          "assuming a rectangular Q with orthonormal columns satisfies QQ^T = I"],
  apps=["numerically stable factorisations (QR, SVD) use orthogonal transformations precisely because they preserve the 2-norm and hence do not amplify error",
        "rotations in graphics and robotics; the orthogonal design matrices of balanced experiments"],
  related={"required_by": ["isometry_characterisation", "spectral_theorem_symmetric", "singular_value_decomposition"]},
  sources=["horn_johnson_2e", "trefethen_bau"], status="reviewed")

N("isometry_characterisation", "theorem", "spectral",
  "For a linear T on a finite-dimensional inner product space the following are equivalent: T preserves the norm (||Tv|| = ||v||); T preserves the inner product (<Tv,Tw> = <v,w>); T^*T = I; T maps some (hence every) orthonormal basis to an orthonormal basis.",
  parseable="||Tv|| = ||v||  <=>  <Tv,Tw> = <v,w>  <=>  T^*T = I  <=>  T maps orthonormal bases to orthonormal bases",
  symbols={"T": "a linear map on a finite-dimensional inner product space"},
  tcn="Well-formed. The step from norm-preservation to inner-product-preservation is POLARISATION, which is why the node depends on polarisation_identity and hence indirectly on char != 2.",
  hyps=["T linear", "V finite-dimensional"],
  field_scope="real_or_complex",
  proof=("norm-preserving implies inner-product-preserving by polarisation; inner-product-preserving says <T^*Tv, w> = <v,w> for all w, hence T^*T = I; the basis statement by direct computation", "polarisation_identity", "core", "LinAlg.isometry_tfae (2x2 Int instance)"),
  spec=["T orthogonal/unitary: the matrix form of the theorem",
        "T a permutation of an orthonormal basis: an isometry"],
  cxd={"linearity": "the Mazur-Ulam phenomenon aside, a NONLINEAR norm-preserving map need not preserve inner products -- e.g. any norm-preserving bijection of the sphere that is not a rotation",
       "finite_dimensionality": "in infinite dimension T^*T = I (an isometry) does NOT give TT^* = I: the right shift on l^2 is a non-surjective isometry. Surjectivity is an extra hypothesis there, supplied automatically here by injective_surjective_equivalence",
       "char_two": "polarisation fails, so norm-preservation would not recover the form"},
  misuse=["assuming an isometry is invertible in infinite dimension (the shift again)",
          "using a real polarisation argument over C"],
  related={"special_case_of": ["cauchy_schwarz"]},
  sources=["axler_lada_4e"], status="reviewed")

N("normal_matrix", "definition", "spectral",
  "A is normal if AA^* = A^*A. The class contains the self-adjoint (A^* = A), skew-adjoint (A^* = -A), and unitary (A^* = A^{-1}) matrices, and is EXACTLY the class of unitarily diagonalisable matrices.",
  parseable="A normal  <=>  AA^* = A^*A;  contains Hermitian, skew-Hermitian, unitary;  = unitarily diagonalisable",
  symbols={"A^*": "the conjugate transpose"},
  tcn="Well-formed for square A. The definition is a commutation condition, which is what makes the 'iff unitarily diagonalisable' characterisation (spectral_theorem_normal) surprising and useful.",
  hyps=["A square"],
  field_scope="real_or_complex",
  spec=["the three named subclasses above",
        "a real ROTATION matrix is orthogonal hence normal, and is unitarily diagonalisable OVER C (eigenvalues e^{+-i theta}) though not over R",
        "a diagonal matrix is normal"],
  cxd={"normality_is_not_automatic": "[[1,1],[0,1]] has AA^* = [[2,1],[1,1]] and A^*A = [[1,1],[1,2]] -- not equal. It is not normal, and indeed not diagonalisable at all",
       "normal_does_not_mean_self_adjoint": "a unitary matrix is normal with eigenvalues on the unit circle, generally not real",
       "sums_and_products_of_normals_need_not_be_normal": "normality is not preserved by addition or multiplication unless the matrices commute"},
  misuse=["assuming a normal matrix has real eigenvalues (only the self-adjoint ones do)",
          "assuming the normal matrices form an algebra"],
  related={"generalizes": ["self_adjoint"], "required_by": ["spectral_theorem_normal", "spectral_radius"]},
  sources=["horn_johnson_2e"], status="reviewed")

N("self_adjoint_real_eigenvalues", "proposition", "spectral",
  "Every eigenvalue of a self-adjoint operator is REAL, and eigenvectors for distinct eigenvalues are ORTHOGONAL. (For a real symmetric matrix this means the complex eigenvalues guaranteed by FTA are in fact real.)",
  parseable="T = T^*, Tv = lambda v, v != 0  =>  lambda in R;  and lambda != mu  =>  E_lambda perp E_mu",
  symbols={"lambda": "an eigenvalue, a priori complex"},
  tcn="Well-formed. For a REAL symmetric matrix one must first pass to C to know an eigenvalue exists (eigenvalue_existence_closed over C); the proposition then says it is real. That two-step structure is why the real spectral theorem is not a triviality.",
  hyps=["T self-adjoint"],
  field_scope="real_or_complex",
  proof=("lambda <v,v> = <Tv,v> = <v,Tv> = conj(lambda)<v,v>, and <v,v> != 0 forces lambda = conj(lambda). Orthogonality: lambda<v,w> = <Tv,w> = <v,Tw> = conj(mu)<v,w> = mu<v,w> using realness, so (lambda - mu)<v,w> = 0", "self_adjoint", "core", "LinAlg.selfadjoint_real_eig (2x2 Int instance: symmetric => discriminant >= 0)"),
  spec=["A = [[a,b],[b,d]] real symmetric: discriminant (a-d)^2 + 4b^2 >= 0 always, so both roots are real -- the 2x2 case verified directly",
        "a covariance matrix has real (indeed nonnegative) eigenvalues, which is why PCA's variances are meaningful numbers"],
  cxd={"self_adjointness": "[[0,-1],[1,0]] is real but NOT symmetric, and its eigenvalues +-i are not real. Symmetry, not realness of the entries, is what forces real eigenvalues",
       "over_C_transpose_is_not_enough": "the complex-symmetric [[1,i],[i,-1]] has A^T = A but eigenvalues both 0 with a defective eigenspace -- it is nilpotent. Hermitian (A^* = A) is the correct hypothesis"},
  misuse=["assuming a real matrix has real eigenvalues",
          "using A^T = A as the criterion over C"],
  apps=["the real-valuedness of PCA variances, of the natural frequencies of a conservative mechanical system, and of quantum-mechanical observables"],
  related={"required_by": ["spectral_theorem_symmetric"]},
  sources=["axler_lada_4e", "horn_johnson_2e"], status="reviewed")

N("rayleigh_quotient", "definition", "spectral",
  "R_A(x) = <Ax,x>/<x,x> for x != 0. A DEFINITION ONLY at this point in the graph: that its extrema over the unit sphere are the extreme eigenvalues is proved downstream (courant_fischer), which is what lets it be used inside the spectral theorem's own proof without circularity (edges/cycles.md).",
  parseable="R_A(x) := <Ax,x>/<x,x>,  x != 0;  R_A(cx) = R_A(x) for c != 0",
  symbols={"R_A": "type: function V\\{0} -> R when A is self-adjoint (real-valued by self_adjoint)"},
  tcn="Well-formed and REAL-VALUED when A is self-adjoint, by the realness of <Ax,x>. Scale-invariance means it is really a function on the projective space, equivalently on the unit sphere -- which is what makes compactness applicable.",
  hyps=["A self-adjoint for real-valuedness", "x != 0"],
  field_scope="real_or_complex",
  spec=["x an eigenvector for lambda: R_A(x) = lambda exactly",
        "A = I: R_A is constantly 1",
        "the range of R_A over all x != 0 is the interval [lambda_min, lambda_max] for self-adjoint A (the numerical range)"],
  cxd={"self_adjointness": "for a non-self-adjoint A, R_A is complex-valued and its range is a REGION of C (the numerical range / field of values), not an interval. The extremal characterisation fails entirely -- [[0,-1],[1,0]] has R_A identically 0 on real vectors while having no real eigenvalue",
       "x_nonzero": "the quotient is undefined at 0"},
  misuse=["reading R_A's maximum as an eigenvalue for a non-symmetric matrix",
          "quoting the extremal property before courant_fischer -- in this capsule that ordering is deliberate"],
  apps=["the power-iteration convergence estimate; the variational principle for the ground-state energy in quantum mechanics and for the fundamental frequency in vibration analysis"],
  related={"required_by": ["spectral_theorem_symmetric", "courant_fischer"]},
  sources=["horn_johnson_2e", "axler_lada_4e"], status="reviewed")

N("spectral_theorem_symmetric", "theorem", "spectral",
  "A real symmetric A has an ORTHONORMAL basis of eigenvectors: A = Q D Q^T with Q orthogonal and D real diagonal. Equivalently a real matrix is orthogonally diagonalisable if and only if it is symmetric.",
  parseable="A = A^T in R^{n x n}  =>  A = Q D Q^T,  Q^TQ = I,  D = diag(lambda_1..lambda_n) real;  and the converse",
  symbols={"Q": "orthogonal, columns the orthonormal eigenvectors", "D": "real diagonal of eigenvalues"},
  tcn="Well-formed over R. The converse direction is immediate ((QDQ^T)^T = QD^TQ^T = QDQ^T), so symmetry is exactly characterised -- an unusually clean iff.",
  hyps=["A real symmetric", "finite-dimensional"],
  field_scope="real_or_complex",
  proof=("induction on n. Existence of one eigenvector: R_A is continuous on the COMPACT unit sphere (compactness_cited), so it attains its maximum (extreme_value_cited) at some x, and a Lagrange/first-order argument shows Ax = R_A(x) x. Its eigenvalue is real by self_adjoint_real_eigenvalues. Then x^perp is A-invariant (because A is self-adjoint), A restricted to it is again symmetric, and the induction runs. ALTERNATIVE ROUTE not encoded as edges: complexify, apply schur_triangularisation, and note that a Hermitian triangular matrix is diagonal", "rayleigh_quotient", "core", "LinAlg.spectral_2x2_symmetric (decide instance: explicit orthogonal diagonalisation of [[2,1],[1,2]]); the general theorem is CITED -- the analysis step is not available Mathlib-free"),
  spec=["A diagonal already: Q = I",
        "A = [[2,1],[1,2]]: eigenvalues 3 and 1 with orthonormal eigenvectors (1,1)/sqrt2 and (1,-1)/sqrt2",
        "A a projection: D has only 0s and 1s, recovering projection_matrix_characterisation",
        "A a covariance matrix: this IS the principal component decomposition"],
  cxd={"symmetry": "[[1,1],[0,1]] is not symmetric and is not diagonalisable at all; [[0,-1],[1,0]] is not symmetric and has no real eigenvalues. Both fail in different ways",
       "realness_of_the_field": "the complex-symmetric [[1,i],[i,-1]] satisfies A^T = A over C and is NOT diagonalisable -- the correct complex hypothesis is Hermitian (spectral_theorem_normal)",
       "finite_dimensionality": "for a self-adjoint operator on an infinite-dimensional Hilbert space there need be no eigenvectors at all (multiplication by x on L^2[0,1]); the spectral theorem becomes a statement about projection-valued measures, entirely outside this capsule"},
  misuse=["applying it to a non-symmetric matrix and expecting an orthogonal eigenbasis",
          "applying it to a complex symmetric matrix"],
  apps=["principal component analysis: the covariance matrix's orthonormal eigenbasis IS the set of principal directions, and the eigenvalues the explained variances",
        "normal modes of a conservative vibrating system; the diagonalisation of a quadratic form in constrained optimisation and in the second-derivative test",
        "the theorem math-statistics cites for quadratic forms in normal variables and for Cochran's theorem"],
  related={"generalizes": [], "required_by": ["spectral_decomposition", "psd_characterisations", "singular_values", "sylvester_law_of_inertia"]},
  sources=["axler_lada_4e", "horn_johnson_2e"], status="reviewed")

N("spectral_theorem_normal", "theorem", "spectral",
  "Over C, A is UNITARILY diagonalisable if and only if A is NORMAL: A = U D U^* with U unitary and D diagonal (generally complex).",
  parseable="A in C^{n x n}:  A = U D U^* with U^*U = I  <=>  AA^* = A^*A",
  symbols={"U": "unitary", "D": "complex diagonal"},
  tcn="Well-formed over C. Note D is complex in general -- realness of the diagonal is the extra content of self-adjointness, not of normality.",
  hyps=["F = C", "finite-dimensional"],
  field_scope="algebraically_closed",
  proof=("forward: A = UDU^* gives AA^* = UDD^*U^* = UD^*DU^* = A^*A since diagonal matrices commute. Backward: by schur_triangularisation A = QTQ^* with T upper triangular; normality of A forces normality of T, and a normal triangular matrix is diagonal (compare the (1,1) entries of TT^* and T^*T and induct)", "schur_triangularisation", "core", "LinAlg.normal_triangular_is_diagonal (2x2 decide instance over Gaussian integers)"),
  spec=["A Hermitian: D is real (self_adjoint_real_eigenvalues), recovering the complex form of spectral_theorem_symmetric",
        "A unitary: D has entries of modulus 1",
        "A skew-Hermitian: D is purely imaginary"],
  cxd={"normality": "[[1,1],[0,1]] is not normal and not diagonalisable",
       "the_field_being_C": "a real orthogonal rotation is normal and is unitarily diagonalisable over C, but NOT orthogonally diagonalisable over R -- its eigenvalues are not real. Over R the correct statement is the real normal form with 2x2 rotation blocks",
       "unitary_versus_merely_invertible": "a diagonalisable non-normal matrix (e.g. [[1,1],[0,2]]) has A = PDP^{-1} with P invertible but NOT unitary. Normality is exactly the obstruction"},
  misuse=["expecting a real orthogonal diagonalisation of a real normal but non-symmetric matrix",
          "confusing diagonalisable (P invertible) with unitarily diagonalisable (P unitary) -- the latter is strictly stronger and is what gives numerical stability"],
  related={"generalizes": ["spectral_theorem_symmetric"]},
  sources=["horn_johnson_2e", "axler_lada_4e"], status="reviewed")

N("spectral_decomposition", "corollary", "spectral",
  "A self-adjoint A equals sum_i lambda_i P_i over its DISTINCT eigenvalues, where P_i is the orthogonal projection onto E_{lambda_i}. The P_i are self-adjoint idempotents with P_iP_j = 0 for i != j and sum_i P_i = I. Consequently f(A) = sum_i f(lambda_i) P_i for any function f on the spectrum.",
  parseable="A = sum_i lambda_i P_i;  P_i^2 = P_i = P_i^*;  P_iP_j = 0 (i != j);  sum P_i = I;  f(A) = sum f(lambda_i) P_i",
  symbols={"P_i": "the spectral projections", "f(A)": "the functional calculus"},
  tcn="Well-formed; the sum is over DISTINCT eigenvalues, so the number of terms is at most n and typically fewer. The functional calculus f(A) is well-defined because the P_i are a resolution of the identity.",
  hyps=["A self-adjoint", "finite-dimensional"],
  field_scope="real_or_complex",
  proof=("group the columns of Q in spectral_theorem_symmetric by eigenvalue; P_i = Q_iQ_i^T for the corresponding block", "spectral_theorem_symmetric", "core", "LinAlg.spectral_resolution (2x2 Int instance: A = 3P_1 + 1P_2)"),
  spec=["A with distinct eigenvalues: each P_i is a rank-one projection q_iq_i^T",
        "f(t) = t^k: recovers A^k = sum lambda_i^k P_i",
        "f(t) = 1/t on an invertible A: A^{-1} = sum (1/lambda_i) P_i",
        "f(t) = e^t: the matrix exponential in closed form"],
  cxd={"self_adjointness": "for a general diagonalisable A the spectral projections are OBLIQUE (P_i = v_iw_i^* with w the LEFT eigenvectors) and are not self-adjoint; the resolution of the identity still holds but the geometry is skewed. For a defective A no such decomposition exists at all",
       "distinctness_of_the_lambda_i": "summing over eigenvalues WITH multiplicity would double-count the projections"},
  misuse=["using f(A) = sum f(lambda_i)P_i for a defective matrix",
          "computing the matrix exponential this way for a non-diagonalisable A"],
  apps=["the matrix functional calculus: exp(At) for linear ODEs, A^{1/2} for whitening, and the matrix square root used to standardise a multivariate normal",
        "Cochran's theorem in statistics is exactly the spectral resolution of I into orthogonal idempotents"],
  related={"special_case_of": ["spectral_theorem_symmetric"]},
  sources=["horn_johnson_2e"], status="reviewed")

N("courant_fischer", "theorem", "spectral",
  "For real symmetric A with eigenvalues lambda_1 >= ... >= lambda_n: lambda_k = max over k-dimensional subspaces S of min_{x in S, x != 0} R_A(x), and dually lambda_k = min over (n-k+1)-dimensional S of the max. In particular lambda_1 = max R_A and lambda_n = min R_A.",
  parseable="lambda_k = max_{dim S = k} min_{0 != x in S} R_A(x) = min_{dim S = n-k+1} max_{0 != x in S} R_A(x)",
  symbols={"S": "a subspace of the stated dimension", "lambda_k": "the k-th largest eigenvalue"},
  tcn="Well-formed given a real symmetric A and its ordered real spectrum (both supplied by spectral_theorem_symmetric). The characterisation is BASIS-FREE and does not mention eigenvectors, which is what makes it robust under perturbation.",
  hyps=["A real symmetric"],
  field_scope="real_or_complex",
  proof=("diagonalise by the spectral theorem so R_A(x) = sum lambda_i |c_i|^2 / sum |c_i|^2, a weighted average of the eigenvalues; then a dimension-counting argument (S of dimension k must meet the span of the last n-k+1 eigenvectors nontrivially) gives both inequalities", "spectral_theorem_symmetric", "core", "LinAlg.rayleigh_bounds (2x2 Int instance: lambda_min <= R_A <= lambda_max)"),
  spec=["k = 1: lambda_1 = max R_A over the unit sphere, and k = n: lambda_n = min",
        "CAUCHY INTERLACING: deleting a row and the matching column of A gives B with lambda_k(A) >= lambda_k(B) >= lambda_{k+1}(A)",
        "WEYL: |lambda_k(A+E) - lambda_k(A)| <= ||E||_2, so symmetric eigenvalues are perfectly conditioned"],
  cxd={"symmetry": "for a non-symmetric matrix the eigenvalues are not real, cannot be ordered, and are NOT well-conditioned: a Jordan block perturbed by epsilon in the corner has eigenvalues moving by epsilon^{1/n}. Everything in this node depends on symmetry",
       "finite_dimensionality": "the min-max principle extends to compact self-adjoint operators, but not to general ones"},
  misuse=["applying eigenvalue-perturbation intuition from the symmetric case to a general matrix, where conditioning can be catastrophic",
          "using the min-max form with the wrong subspace dimension (the two forms use k and n-k+1)"],
  apps=["eigenvalue interlacing under adding a data point or a constraint; the stability of PCA directions under sampling noise",
        "the Eckart-Young bound and singular-value perturbation theory"],
  related={"generalizes": ["rayleigh_quotient"], "required_by": ["eckart_young"]},
  sources=["horn_johnson_2e", "trefethen_bau"], status="reviewed")

N("quadratic_form", "definition", "spectral",
  "q(x) = x^T A x with A symmetric. When char F != 2 the symmetric A representing a given q is UNIQUE, and the associated bilinear form is recovered by polarisation: b(x,y) = (q(x+y) - q(x) - q(y))/2.",
  parseable="q(x) := x^T A x, A = A^T;  A unique given q when char F != 2;  b(x,y) = (q(x+y) - q(x) - q(y))/2",
  symbols={"q": "type: function F^n -> F, homogeneous of degree 2",
           "A": "the symmetric representing matrix"},
  tcn="Well-formed. Uniqueness of the SYMMETRIC representative is the substantive claim: any A gives a form, but x^TAx = x^T((A+A^T)/2)x, so only the symmetric part matters -- and forming (A+A^T)/2 divides by 2.",
  hyps=["A symmetric", "char F != 2 for uniqueness"],
  field_scope="char_not_2",
  proof=("x^TAx = x^T A^T x since both are 1x1, so x^TAx = x^T((A+A^T)/2)x; uniqueness by polarisation", "characteristic_not_two", "core", "LinAlg.quadratic_symmetric_unique (2x2 Int instance with the 2*expr/2 idiom)"),
  spec=["n = 1: q(x) = ax^2",
        "A = I: q(x) = ||x||^2",
        "the second-order term of a Taylor expansion, with A the Hessian -- symmetric by equality of mixed partials"],
  cxd={"characteristic_not_two": "over F_2, q(x) = x_1x_2 comes from A = [[0,1],[0,0]] and from A = [[0,0],[1,0]] and from [[0,1],[1,0]] -- the symmetric representative is not unique, and worse, the polarisation b(x,y) = 2x^TAy = 0 vanishes identically. Quadratic forms in characteristic 2 are a genuinely separate theory",
       "symmetry": "without restricting to symmetric A the representation is never unique in any characteristic"},
  misuse=["symmetrising as (A + A^T)/2 without checking the characteristic",
          "confusing the quadratic form's transformation law (congruence, P^TAP) with an operator's (similarity, P^{-1}AP) -- see congruence"],
  apps=["the second-derivative test in optimisation: the Hessian's definiteness classifies critical points",
        "variance of a linear combination: Var(a^TX) = a^T Sigma a is a quadratic form, PSD because Sigma is"],
  related={"required_by": ["congruence", "positive_definite", "sylvester_law_of_inertia", "courant_fischer"]},
  sources=["hoffman_kunze_2e", "horn_johnson_2e"], status="reviewed")

N("congruence", "definition", "spectral",
  "A ~_c B if B = P^T A P for some invertible P. This is the transformation law of QUADRATIC FORMS under a change of variables x = Py, and it is DIFFERENT from similarity (P^{-1}AP) unless P is orthogonal.",
  parseable="A ~_c B  <=>  B = P^T A P, P invertible;  q_B(y) = q_A(Py)",
  symbols={"~_c": "congruence, type: equivalence relation on symmetric matrices"},
  tcn="Well-formed as an equivalence relation (reflexive with P = I, symmetric via P^{-1}, transitive by composition) and it preserves symmetry: (P^TAP)^T = P^TA^TP = P^TAP.",
  field_scope="any_field",
  proof=("equivalence-relation axioms; the change-of-variables reading by substituting x = Py into x^TAx", "quadratic_form", "core", "LinAlg.congruence_equiv"),
  spec=["P orthogonal: congruence and similarity COINCIDE, which is exactly why spectral_theorem_symmetric can be read either way",
        "P diagonal with entries 1/sqrt(|lambda_i|): brings a diagonalised form to a matrix of +-1s and 0s, the canonical form of sylvester_law_of_inertia"],
  cxd={"congruence_is_not_similarity": "A = I_2 and B = diag(4,9) = P^T I P with P = diag(2,3) are CONGRUENT but not SIMILAR -- their eigenvalues differ entirely. So eigenvalues are NOT congruence invariants; only their SIGNS are (sylvester_law_of_inertia). Using similarity invariants (trace, determinant, eigenvalues) to compare quadratic forms is the standard error",
       "invertibility_of_P": "a singular P can only degrade the form and gives no equivalence relation"},
  misuse=["quoting eigenvalues as invariants of a quadratic form",
          "diagonalising a quadratic form by similarity when the change of variables is not orthogonal"],
  related={"contrasts_with": ["similarity"], "required_by": ["sylvester_law_of_inertia", "simultaneous_diagonalisation"]},
  sources=["hoffman_kunze_2e", "horn_johnson_2e"], status="reviewed")

N("positive_definite", "definition", "spectral",
  "A real SYMMETRIC A is positive definite (A > 0) if x^T A x > 0 for every x != 0, and positive SEMIdefinite (A >= 0) if x^TAx >= 0 for all x. Negative (semi)definite by reversing; INDEFINITE otherwise.",
  parseable="A > 0  <=>  A = A^T and x^TAx > 0 for all x != 0;  A >= 0  <=>  A = A^T and x^TAx >= 0",
  symbols={"A > 0, A >= 0": "the Loewner ordering notation; A >= B means A - B >= 0"},
  tcn="Well-formed only over an ORDERED field (to say '> 0') and conventionally only for SYMMETRIC A (so that x^TAx captures all of A -- see quadratic_form). Both restrictions are why the node carries edges to ordered_field_hyp and self_adjoint.",
  hyps=["A symmetric", "F ordered (F = R here)"],
  field_scope="ordered_field",
  spec=["A = I: positive definite", "A = 0: positive semidefinite but not definite",
        "any Gram matrix is PSD, and definite iff the vectors are independent (gram_matrix)",
        "a covariance matrix is PSD, and definite iff no linear combination of the variables is degenerate"],
  cxd={"symmetry": "for a NON-symmetric A the condition x^TAx > 0 depends only on (A+A^T)/2, so it cannot characterise A. [[1,-3],[3,1]] satisfies x^TAx = ||x||^2 > 0 yet has complex eigenvalues -- 'positive definite' in the eigenvalue sense fails while the quadratic-form condition holds. The two notions agree ONLY for symmetric A, which is why symmetry is built into the definition",
       "the_ordered_field": "over C, x^TAx is complex; the Hermitian form x^*Ax is real exactly when A is Hermitian, and that is the correct complex definition",
       "definite_versus_semidefinite": "diag(1,0) is PSD, singular, and NOT positive definite -- the distinction is exactly invertibility"},
  misuse=["calling a non-symmetric matrix positive definite without saying which sense",
          "assuming positive entries means positive definite: [[1,2],[2,1]] has all positive entries and eigenvalues 3, -1 -- INDEFINITE. Conversely [[2,-1],[-1,2]] has negative entries and is positive definite"],
  apps=["covariance matrices, Hessians at a minimum, kernel matrices in SVMs and Gaussian processes, and the mass and stiffness matrices of a stable structure",
        "the Fisher information matrix in math-statistics is PSD, which is what makes the Cramer-Rao bound meaningful"],
  related={"required_by": ["psd_characterisations", "cholesky_factorisation", "gram_matrix", "singular_values"]},
  sources=["horn_johnson_2e", "boyd_vandenberghe"], status="reviewed")

N("gram_matrix", "construction", "spectral",
  "For vectors v_1,...,v_k in an inner product space, G_{ij} = <v_j, v_i> (equivalently G = A^*A with A the matrix of columns). G is Hermitian positive SEMIdefinite, rank G = dim span(v_i), and G is positive DEFINITE iff the v_i are linearly independent.",
  parseable="G := A^*A, G_{ij} = <v_j,v_i>;  G >= 0 always;  G > 0  <=>  (v_i) independent;  rank G = rank A",
  symbols={"G": "the Gram matrix, type: k x k Hermitian PSD",
           "det G": "the Gram determinant, the squared volume of the parallelepiped"},
  tcn="Well-formed; Hermitian because (A^*A)^* = A^*A, and PSD because x^*A^*Ax = ||Ax||^2 >= 0. Both facts are one line and are the reason PSD matrices are ubiquitous.",
  hyps=["an inner product space"],
  field_scope="real_or_complex",
  proof=("x^*Gx = ||Ax||^2 >= 0, with equality iff Ax = 0; so G is definite iff null(A) = {0} iff the columns are independent. rank G = rank A because null(A^*A) = null(A)", "positive_definite", "core", "LinAlg.gram_psd (Int instance: x^T A^T A x = ||Ax||^2)"),
  spec=["k = 1: G = [||v_1||^2]",
        "the v_i orthonormal: G = I",
        "A^TA in the normal equations IS a Gram matrix, which is why least_squares has a unique solution exactly under full column rank",
        "det G is the squared volume of the parallelepiped spanned by the v_i -- zero iff they are dependent"],
  cxd={"independence_for_definiteness": "with a repeated vector G is singular; in regression this is exact collinearity, and near-collinearity makes G nearly singular and the fit ill-conditioned (condition_number)",
       "null(A^*A) = null(A) needs the CONJUGATE": "over C with A^TA instead, A = [[1, i]] gives a singular A^TA despite full rank -- see conjugate_transpose"},
  misuse=["forming the Gram matrix to solve least squares (it squares the condition number -- see least_squares)",
          "using A^TA over C"],
  apps=["kernel matrices in machine learning ARE Gram matrices, which is why Mercer's condition is positive semidefiniteness",
        "the covariance matrix of a random vector is the Gram matrix of the centred variables under the E[XY] inner product"],
  related={"required_by": ["psd_characterisations", "singular_values"]},
  sources=["horn_johnson_2e"], status="reviewed")

N("cholesky_factorisation", "construction", "spectral",
  "A real symmetric POSITIVE DEFINITE A factors UNIQUELY as A = LL^T with L lower triangular having strictly positive diagonal. Cost ~ (1/3)n^3, half that of LU, and NO PIVOTING is ever required.",
  parseable="A > 0 symmetric  =>  A = LL^T uniquely, L lower triangular with L_{ii} > 0;  cost ~ n^3/3",
  symbols={"L": "the Cholesky factor", "L_{ii}": "required strictly positive, which fixes uniqueness"},
  tcn="Well-formed. Positive definiteness is what makes every square root taken in the algorithm a square root of a POSITIVE number, so the factorisation exists over R without ever leaving R.",
  hyps=["A symmetric positive definite"],
  field_scope="ordered_field",
  proof=("induction on n: A = [[a, b^T],[b, A']] with a > 0 (since e_1^TAe_1 = a); factor out, and the remaining block is the Schur complement A' - bb^T/a, which is again positive definite (schur_complement)", "positive_definite", "core", "LinAlg.cholesky_2x2 (decide instance: A = [[4,2],[2,5]] gives L = [[2,0],[1,2]])"),
  spec=["A = I: L = I", "n = 1: A = [a] with a > 0 gives L = [sqrt a]",
        "A = R^TR from qr_factorisation applied to the normal equations: the Cholesky factor of A^TA is exactly the R of the QR of A"],
  cxd={"positive_definiteness": "A = [[0,1],[1,0]] is symmetric, invertible, and INDEFINITE: the algorithm's first step needs sqrt(0) then divides by it. Cholesky failing is in fact the standard NUMERICAL TEST for positive definiteness -- attempt the factorisation and see whether it completes",
       "semidefinite_case": "a singular PSD A has a Cholesky-like factorisation with a zero on the diagonal, but it is no longer unique"},
  misuse=["applying Cholesky to a symmetric indefinite matrix (use LDL^T or Bunch-Kaufman instead)",
          "testing positive definiteness by computing all eigenvalues when attempting Cholesky is ~3x cheaper"],
  apps=["sampling from a multivariate normal: x = mu + L z with z standard normal has covariance LL^T = Sigma",
        "the standard solver for the normal equations and for every kernel-method linear system; Kalman filter covariance updates"],
  related={"special_case_of": ["lu_factorisation"], "required_by": ["psd_characterisations", "simultaneous_diagonalisation"]},
  sources=["golub_van_loan_4e", "higham_asna_2e"], status="reviewed")

N("psd_characterisations", "theorem", "spectral",
  "For real symmetric A the following are EQUIVALENT: A is positive definite; every eigenvalue is > 0; every LEADING PRINCIPAL minor is > 0 (Sylvester's criterion); A = B^TB for some B of full column rank; A has a Cholesky factorisation LL^T with positive diagonal; A = A^TA-form Gram matrix of an independent set. For positive SEMIdefiniteness, replace > by >= and 'leading principal' by ALL principal minors.",
  parseable="A > 0  <=>  all eigenvalues > 0  <=>  all leading principal minors > 0  <=>  A = B^TB with rank B = n  <=>  A = LL^T Cholesky",
  symbols={"leading principal minor": "det of the top-left k x k block, k = 1..n"},
  tcn="Well-formed for SYMMETRIC A only. The semidefinite version genuinely needs ALL principal minors, not merely the leading ones -- a distinction that is easy to get wrong and is recorded as a counterexample below.",
  hyps=["A real symmetric"],
  field_scope="ordered_field",
  proof=("eigenvalues: diagonalise by spectral_theorem_symmetric so x^TAx = sum lambda_i y_i^2. Sylvester's criterion by induction using the schur_complement. Factorisations: B = D^{1/2}Q^T from the spectral decomposition, or the Cholesky construction", "spectral_theorem_symmetric", "core", "LinAlg.psd_tfae_2x2 (decide instance: [[2,1],[1,2]] positive definite by all four criteria)"),
  spec=["n = 1: [a] > 0 iff a > 0 iff its one minor is positive",
        "n = 2: A > 0 iff a_{11} > 0 and det A > 0 -- the two leading minors",
        "A a covariance matrix: PSD, definite iff no exact linear relation among the variables"],
  cxd={"leading_versus_all_principal_minors": "A = diag(0, -1) has leading principal minors 0 and 0 -- neither negative -- yet A is NOT positive semidefinite (x = e_2 gives -1). For SEMIdefiniteness one must check ALL principal minors, including det of the {2} block, which is -1. Sylvester's criterion with LEADING minors characterises DEFINITENESS only",
       "symmetry": "for non-symmetric A the minor criterion says nothing: [[1,-3],[3,1]] has positive leading minors (1 and 10) and complex eigenvalues",
       "strictness": "diag(1,0) has leading minors 1 and 0, so it fails strict Sylvester -- correctly, since it is semidefinite but not definite"},
  misuse=["using leading principal minors to test positive SEMIdefiniteness (see the diag(0,-1) witness)",
          "applying any of these criteria to a non-symmetric matrix"],
  apps=["testing a Hessian at a critical point; validating a covariance or kernel matrix; the PSD constraint in semidefinite programming",
        "the Loewner ordering Var(estimator) >= CRLB in math-statistics is a PSD statement in exactly this sense"],
  related={"required_by": []},
  sources=["horn_johnson_2e", "boyd_vandenberghe"], status="reviewed")

N("sylvester_law_of_inertia", "theorem", "spectral",
  "The numbers (n_+, n_-, n_0) of positive, negative, and zero eigenvalues of a real symmetric A -- its INERTIA -- are invariant under congruence. Two real quadratic forms are congruent iff they have the same inertia, so the signature is a COMPLETE invariant.",
  parseable="A ~_c B  =>  inertia(A) = inertia(B);  and conversely.  Canonical form: diag(I_{n_+}, -I_{n_-}, 0)",
  symbols={"(n_+, n_-, n_0)": "the inertia", "signature": "n_+ - n_-"},
  tcn="Well-formed over an ORDERED field (to classify signs). Over C every nondegenerate form is congruent to the identity, so the inertia carries no information -- the theorem is genuinely about real (or ordered-field) forms.",
  hyps=["A real symmetric", "F ordered"],
  field_scope="ordered_field",
  proof=("the spectral theorem plus scaling gives the canonical form diag(I,-I,0), so every A is congruent to one. Invariance: if P^TAP = diag(I_{p},-I_{q},0) and also = diag(I_{p'},-I_{q'},0), a dimension count on the maximal subspace where the form is positive definite (which is congruence-invariant) forces p = p'", "congruence", "core", "LinAlg.inertia_2x2 (decide instance: diag(4,-9) and diag(1,-1) share inertia (1,1,0))"),
  spec=["A positive definite: inertia (n,0,0)",
        "A = diag(1,-1) and B = diag(4,-9): congruent (P = diag(2,3)) with the SAME inertia, though with completely different eigenvalues -- the sharpest illustration of similarity versus congruence",
        "the index n_- is the Morse index of a critical point"],
  cxd={"the_ordered_field": "over C, diag(1,-1) = P^T I P with P = diag(1, i), so every nondegenerate complex symmetric form is congruent to I and the inertia is meaningless. Ordering is essential",
       "eigenvalues_are_not_preserved": "only their SIGNS are, as the diag(4,-9) example shows. Quoting eigenvalues as form invariants is the standard error",
       "symmetry": "no inertia is defined for a non-symmetric matrix"},
  misuse=["using eigenvalues rather than their signs to compare quadratic forms",
          "applying inertia over C"],
  apps=["the Morse index in optimisation and differential topology; the classification of conics and quadrics by signature",
        "the inertia of the KKT matrix is the standard test that an interior-point step is a descent direction"],
  related={"contrasts_with": ["similar_invariants"]},
  sources=["hoffman_kunze_2e", "horn_johnson_2e"], status="reviewed")

N("simultaneous_diagonalisation", "theorem", "spectral",
  "Two real symmetric matrices A, B with B POSITIVE DEFINITE are simultaneously diagonalisable by CONGRUENCE: some invertible P gives P^TBP = I and P^TAP diagonal. Separately, two NORMAL matrices are simultaneously UNITARILY diagonalisable if and only if they COMMUTE.",
  parseable="A, B symmetric, B > 0  =>  exists P: P^TBP = I, P^TAP diagonal.  A, B normal:  simultaneously unitarily diagonalisable  <=>  AB = BA",
  symbols={"P": "invertible (congruence case) or unitary (commuting case)"},
  tcn="Well-formed. TWO distinct theorems sharing a name, with different hypotheses and different transformation laws -- congruence in the first, unitary similarity in the second. Conflating them is the standard confusion.",
  hyps=["A, B symmetric with B positive definite; OR A, B normal and commuting"],
  field_scope="real_or_complex",
  proof=("congruence case: take the Cholesky factor B = LL^T, set C = L^{-1}AL^{-T} which is symmetric, diagonalise it orthogonally as C = QDQ^T, and put P = L^{-T}Q. Commuting case: each eigenspace of A is B-invariant, so diagonalise B within each", "cholesky_factorisation", "core", "LinAlg.simul_diag_2x2 (decide instance: the generalised eigenproblem for a 2x2 pair)"),
  spec=["B = I: the congruence case reduces to the ordinary spectral theorem",
        "A, B commuting Hermitian: BOTH theorems apply and give the same answer",
        "the generalised eigenproblem Ax = lambda Bx is exactly the congruence case, and its solutions are the diagonal entries"],
  cxd={"positive_definiteness_of_B": "A = [[0,1],[1,0]] and B = [[1,0],[0,-1]] are both symmetric with B indefinite, and no congruence diagonalises both. Definiteness of ONE of the pair is essential",
       "commutativity_in_the_normal_case": "the two Pauli-like matrices [[0,1],[1,0]] and [[1,0],[0,-1]] are Hermitian and do NOT commute; no single unitary diagonalises both. This is the linear-algebra core of the uncertainty principle",
       "congruence_is_not_similarity": "the first theorem's P is not orthogonal, so the diagonal entries of P^TAP are NOT the eigenvalues of A -- they are the generalised eigenvalues of (A,B)"},
  misuse=["reading the diagonal of P^TAP as eigenvalues of A in the congruence case",
          "assuming any two symmetric matrices can be simultaneously diagonalised"],
  apps=["the generalised eigenproblem of structural vibration (stiffness and mass matrices, with mass positive definite); linear discriminant analysis (between- and within-class scatter)",
        "whitening followed by PCA is exactly this construction"],
  sources=["horn_johnson_2e", "golub_van_loan_4e"], status="reviewed")

N("singular_values", "definition", "spectral",
  "The singular values sigma_1 >= ... >= sigma_p >= 0 (p = min(m,n)) of A in F^{m x n} are the nonnegative square roots of the eigenvalues of A^*A (equivalently of AA^*). rank A = the number of NONZERO singular values.",
  parseable="sigma_i := sqrt(lambda_i(A^*A));  sigma_1 >= ... >= sigma_p >= 0;  rank A = #{i : sigma_i > 0}",
  symbols={"sigma_i": "type: nonnegative real", "p": "min(m,n)"},
  tcn="Well-formed: A^*A is Hermitian POSITIVE SEMIDEFINITE (gram_matrix), so its eigenvalues are real and nonnegative (spectral_theorem_symmetric, positive_definite) and the square roots are real. Every step of this justification is a separate prerequisite, which is why the node has five incoming edges.",
  hyps=["A in F^{m x n}"],
  field_scope="real_or_complex",
  proof=("A^*A is Hermitian PSD by gram_matrix; its spectrum is real and nonnegative; AA^* has the same nonzero eigenvalues (since AB and BA share nonzero spectrum)", "gram_matrix", "core", "LinAlg.singular_values_nonneg (Int instance: A^TA PSD)"),
  spec=["A square symmetric PSD: the singular values ARE the eigenvalues",
        "A square symmetric indefinite: sigma_i = |lambda_i| -- the absolute values, so SVD loses sign information the eigendecomposition keeps",
        "A orthogonal: all singular values 1",
        "A = uv^*: one nonzero singular value ||u|| ||v||"],
  cxd={"singular_values_are_not_eigenvalues": "[[0,1],[0,0]] has both eigenvalues 0 but singular values 1 and 0. A nilpotent matrix can have large singular values -- the two spectra measure different things (spectral_radius versus norm)",
       "the_conjugate_matters": "over C, using A^TA instead of A^*A gives the wrong (possibly negative or complex) values -- see conjugate_transpose"},
  misuse=["treating singular values as eigenvalues for a non-symmetric matrix",
          "computing them by forming A^*A explicitly: that squares the condition number; use a direct SVD algorithm"],
  related={"required_by": ["singular_value_decomposition", "matrix_norms", "condition_number"]},
  sources=["horn_johnson_2e", "trefethen_bau"], status="reviewed")

N("singular_value_decomposition", "theorem", "spectral",
  "Every A in F^{m x n} factors as A = U Sigma V^* with U in F^{m x m} and V in F^{n x n} unitary and Sigma in R^{m x n} diagonal with entries sigma_1 >= ... >= sigma_p >= 0. Equivalently A = sum_{i=1}^r sigma_i u_i v_i^* with r = rank A. NO hypothesis on A whatsoever -- not square, not symmetric, not full rank.",
  parseable="A = U Sigma V^*,  U^*U = I_m, V^*V = I_n, Sigma diagonal nonnegative nonincreasing;  A = sum_{i<=r} sigma_i u_i v_i^*",
  symbols={"u_i, v_i": "the left and right singular vectors", "r": "rank A"},
  tcn="Well-formed for EVERY matrix over R or C. The unqualified generality is the point: where the eigendecomposition needs diagonalisability and the spectral theorem needs symmetry, the SVD needs nothing.",
  hyps=["F = R or C"],
  field_scope="real_or_complex",
  proof=("diagonalise the Hermitian PSD A^*A = V D V^* by spectral_theorem_symmetric; set sigma_i = sqrt(d_i) and u_i = Av_i/sigma_i for sigma_i > 0, which are orthonormal by construction; extend to an orthonormal basis of F^m by gram_schmidt", "singular_values", "core", "LinAlg.svd_2x2 (decide instance: explicit SVD of [[3,0],[0,2]] and of a rank-1 matrix); the general theorem is CITED -- square roots are not available Mathlib-free"),
  spec=["A symmetric PSD: U = V and the SVD is the eigendecomposition",
        "A orthogonal: Sigma = I",
        "A = uv^*: a single term, sigma_1 = ||u|| ||v||",
        "the geometric reading: every linear map is a rotation, then an axis-aligned scaling, then another rotation"],
  cxd={"uniqueness_fails": "the singular VALUES are unique, but U and V are not: any repeated singular value allows rotating within its subspace, and even for distinct values each pair (u_i, v_i) can be multiplied by a common unit scalar. Claims of a 'unique SVD' are wrong",
       "no_hypothesis_can_be_dropped_because_there_are_none": "the only requirement is F in {R, C}. Over a general field there is no SVD, because there is no notion of nonnegative square root"},
  misuse=["expecting a unique U and V",
          "interpreting singular vectors as eigenvectors of A"],
  apps=["principal component analysis (the SVD of the centred data matrix), latent semantic analysis, image compression, and every low-rank approximation method -- via eckart_young",
        "the numerically definitive way to compute rank, null space, range, and pseudoinverse of a matrix"],
  related={"generalizes": ["spectral_theorem_symmetric"], "required_by": ["svd_four_subspaces", "moore_penrose_pseudoinverse", "eckart_young"]},
  sources=["trefethen_bau", "golub_van_loan_4e"], status="reviewed")

N("svd_four_subspaces", "corollary", "spectral",
  "With r = rank A: u_1..u_r is an orthonormal basis of col(A), u_{r+1}..u_m of null(A^*); v_1..v_r of row(A) (i.e. col(A^*)), and v_{r+1}..v_n of null(A). The SVD delivers ORTHONORMAL bases for all four fundamental subspaces at once.",
  parseable="col(A) = span(u_1..u_r);  null(A^*) = span(u_{r+1}..u_m);  row(A) = span(v_1..v_r);  null(A) = span(v_{r+1}..v_n)",
  symbols={"r": "rank A, = the number of nonzero singular values"},
  tcn="Well-formed. This upgrades four_subspaces (dimensions) and adjoint_kernel_image (orthogonality) to explicit orthonormal bases -- the strongest form of the four-subspace picture.",
  hyps=["A in F^{m x n}", "F = R or C"],
  field_scope="real_or_complex",
  proof=("Av_i = sigma_i u_i shows Av_i = 0 exactly for i > r, giving the null space; the u_i for i <= r then span the image, and the orthogonal complements follow from adjoint_kernel_image", "singular_value_decomposition", "core", "LinAlg.svd_subspace_bases (2x2 rank-1 decide instance)"),
  spec=["A of full column rank: no v's left over, null(A) = {0}",
        "A square invertible: r = n = m and both null spaces are trivial"],
  cxd={"numerical_rank": "deciding r requires a THRESHOLD on the singular values in floating point; 'rank' is not a computable property of a floating-point matrix, and the SVD makes this explicit (small nonzero sigma) where elimination hides it"},
  misuse=["reading r off exact zeros of Sigma in a numerical computation without a tolerance"],
  related={"generalizes": ["four_subspaces"], "required_by": ["moore_penrose_pseudoinverse"]},
  sources=["strang_5e", "trefethen_bau"], status="reviewed")

N("moore_penrose_pseudoinverse", "construction", "spectral",
  "A^+ = V Sigma^+ U^* where Sigma^+ inverts the nonzero singular values and transposes. It is the UNIQUE matrix satisfying the four Penrose conditions (AA^+A = A, A^+AA^+ = A^+, (AA^+)^* = AA^+, (A^+A)^* = A^+A). A^+b is the MINIMUM-NORM least-squares solution, and AA^+ is the orthogonal projection onto col(A).",
  parseable="A^+ := V Sigma^+ U^*;  the four Penrose conditions hold and characterise A^+;  A^+b = argmin{||x|| : x minimises ||Ax-b||}",
  symbols={"A^+": "the pseudoinverse, type: element of F^{n x m}",
           "Sigma^+": "diagonal with 1/sigma_i for sigma_i > 0, else 0"},
  tcn="Well-formed for EVERY A, including rank-deficient and rectangular. Uniqueness under the four conditions is what makes A^+ canonical rather than one generalised inverse among many.",
  hyps=["F = R or C"],
  field_scope="real_or_complex",
  proof=("existence from the SVD by direct verification of the four conditions; uniqueness by a standard algebraic argument from them. The minimum-norm property because A^+b lies in row(A) = null(A)^perp, and any other minimiser adds an element of null(A), which by Pythagoras only increases the norm", "singular_value_decomposition", "core", "LinAlg.penrose_conditions (2x2 rank-1 decide instance)"),
  spec=["A invertible: A^+ = A^{-1}",
        "A of full column rank: A^+ = (A^*A)^{-1}A^*, the least-squares formula",
        "A of full row rank: A^+ = A^*(AA^*)^{-1}, the minimum-norm solution of an underdetermined system",
        "A = 0: A^+ = 0"],
  cxd={"discontinuity_in_A": "A^+ is NOT a continuous function of A across a rank change: for A_eps = diag(1, eps), A_eps^+ = diag(1, 1/eps) blows up as eps -> 0, while A_0^+ = diag(1,0). This is the practical reason a truncated (regularised) pseudoinverse is used in practice, and the reason a rank tolerance is unavoidable",
       "(AB)^+ != B^+A^+": "the reversal rule holds for inverses but FAILS for pseudoinverses in general -- a common and silent error"},
  misuse=["using the reversal rule for pseudoinverses",
          "applying A^+ numerically without truncating tiny singular values"],
  apps=["the canonical solution of rank-deficient least squares; ridge regression as a regularised pseudoinverse; the minimum-norm solution in underdetermined inverse problems and in over-parameterised model fitting"],
  related={"generalizes": ["invertible_matrix"]},
  sources=["golub_van_loan_4e", "horn_johnson_2e"], status="reviewed")

N("matrix_norms", "definition", "spectral",
  "The SPECTRAL (operator 2-) norm ||A||_2 = max_{||x||=1} ||Ax|| = sigma_1, and the FROBENIUS norm ||A||_F = sqrt(tr(A^*A)) = sqrt(sum_i sigma_i^2). Both are submultiplicative and UNITARILY INVARIANT, and ||A||_2 <= ||A||_F <= sqrt(r) ||A||_2.",
  parseable="||A||_2 = sigma_1;  ||A||_F = sqrt(sum sigma_i^2) = sqrt(tr(A^*A));  ||AB|| <= ||A|| ||B||;  ||UAV|| = ||A|| for unitary U,V",
  symbols={"||A||_2": "the spectral/operator norm", "||A||_F": "the Frobenius norm"},
  tcn="Well-formed. Both are genuine norms on F^{m x n}; the Frobenius norm is the norm induced by the Frobenius INNER PRODUCT <A,B> = tr(B^*A), while the spectral norm comes from NO inner product (it fails the parallelogram law).",
  hyps=["F = R or C"],
  field_scope="real_or_complex",
  proof=("||A||_2 = sigma_1 from the SVD: ||Ax|| = ||Sigma V^*x|| is maximised along v_1. ||A||_F^2 = tr(A^*A) = sum of the eigenvalues of A^*A = sum sigma_i^2. Unitary invariance because U and V do not change singular values", "singular_values", "core", "LinAlg.frobenius_trace (Int instance: ||A||_F^2 = tr(A^TA))"),
  spec=["A = I_n: ||I||_2 = 1 but ||I||_F = sqrt(n) -- the norms differ substantially",
        "A of rank 1: the two norms coincide",
        "A unitary: ||A||_2 = 1, ||A||_F = sqrt(n)"],
  cxd={"the_entrywise_max_is_not_submultiplicative": "max_{ij}|A_{ij}| is a norm but NOT submultiplicative: for A = B = [[1,1],[1,1]], the max norm of AB = [[2,2],[2,2]] is 2 > 1 * 1. Submultiplicativity must be checked, not assumed",
       "the_spectral_norm_is_not_from_an_inner_product": "it fails the parallelogram law, so there is no 'spectral inner product' and no projection theory for it",
       "norms_are_not_the_spectral_radius": "for the nilpotent [[0,1],[0,0]], rho = 0 while ||A||_2 = 1 -- see spectral_radius"},
  misuse=["assuming every matrix norm is submultiplicative",
          "using ||A||_F where ||A||_2 is meant in a perturbation bound (they differ by up to sqrt(r))"],
  apps=["the Frobenius norm is the loss function of matrix factorisation and of the Eckart-Young approximation; the spectral norm bounds error amplification and defines the condition number",
        "Lipschitz bounds on neural network layers use the spectral norm"],
  related={"required_by": ["eckart_young", "condition_number", "spectral_radius"]},
  sources=["horn_johnson_2e", "trefethen_bau"], status="reviewed")

N("eckart_young", "theorem", "spectral",
  "The best rank-k approximation to A in BOTH the spectral and the Frobenius norm is the truncated SVD A_k = sum_{i=1}^k sigma_i u_i v_i^*, with errors ||A - A_k||_2 = sigma_{k+1} and ||A - A_k||_F = sqrt(sum_{i>k} sigma_i^2).",
  parseable="min_{rank B <= k} ||A - B||_2 = sigma_{k+1};  min_{rank B <= k} ||A - B||_F = sqrt(sum_{i>k} sigma_i^2);  both attained by A_k",
  symbols={"A_k": "the rank-k truncation of the SVD", "sigma_{k+1}": "the first discarded singular value"},
  tcn="Well-formed. The remarkable content is that the SAME truncation is optimal for two quite different norms -- and in fact for every unitarily invariant norm (Mirsky's theorem, cited).",
  hyps=["k < rank A", "F = R or C"],
  field_scope="real_or_complex",
  proof=("the error value by direct computation. Optimality: any B of rank <= k has a null space of dimension >= n-k, which must intersect span(v_1..v_{k+1}) nontrivially; on that intersection ||(A-B)x|| = ||Ax|| >= sigma_{k+1}||x|| by courant_fischer", "singular_value_decomposition", "core", "LinAlg.eckart_young_2x2 (decide instance: best rank-1 approximation to diag(3,2) is diag(3,0), error 2)"),
  spec=["k = rank A: zero error", "k = 0: the error is ||A||_2 = sigma_1, correctly",
        "A = diag(3,2): the best rank-1 approximation is diag(3,0) with spectral error 2"],
  cxd={"the_norm_being_unitarily_invariant": "under the ENTRYWISE max norm the truncated SVD is NOT optimal -- optimality is specific to unitarily invariant norms, and this is exactly Mirsky's generalisation",
       "uniqueness": "if sigma_k = sigma_{k+1} the optimal A_k is not unique, because the truncation can be taken in different directions within the tied subspace",
       "structure_is_not_preserved": "the truncated SVD of a nonnegative matrix generally has negative entries, and of a sparse matrix is dense. Structured low-rank approximation (NMF, sparse PCA) is a different and much harder problem with no closed form"},
  misuse=["assuming the truncated SVD is the best STRUCTURED approximation (nonnegative, sparse, Hankel) -- it is the best unconstrained one",
          "reporting a unique answer when singular values are tied"],
  apps=["PCA's dimension reduction is exactly this theorem: retaining the top k components is optimal in mean squared error",
        "image and model compression, latent semantic indexing, and the theoretical justification of spectral methods generally"],
  related={"approximates": ["singular_value_decomposition"]},
  sources=["eckart_young_1936", "trefethen_bau"], status="reviewed")

N("condition_number", "diagnostic", "spectral",
  "kappa_2(A) = sigma_1/sigma_n = ||A||_2 ||A^{-1}||_2 for invertible A. It bounds the relative error amplification: ||dx||/||x|| <= kappa(A) (||db||/||b|| + ||dA||/||A||) to first order. LARGE kappa means ILL-CONDITIONED, which is NOT the same as singular.",
  parseable="kappa_2(A) := sigma_1/sigma_n = ||A||_2 ||A^{-1}||_2;  relative error amplification bounded by kappa;  kappa >= 1 always",
  symbols={"kappa_2(A)": "type: real >= 1", "dx, db": "perturbations"},
  tcn="Well-formed for invertible A; for singular A, kappa = infinity by convention, and for rectangular A one uses sigma_1/sigma_r. Note kappa is SCALE-INVARIANT: kappa(cA) = kappa(A), unlike the determinant.",
  hyps=["A invertible"],
  field_scope="real_or_complex",
  proof=("from ||A||_2 = sigma_1 and ||A^{-1}||_2 = 1/sigma_n; the perturbation bound by expanding (A+dA)(x+dx) = b+db and using submultiplicativity. The floating-point interpretation (roughly log10(kappa) digits lost) is a CITED numerical-analysis heuristic", "matrix_norms", "core", "LinAlg.condition_ge_one (sigma_1 >= sigma_n)"),
  spec=["A orthogonal: kappa = 1, the best possible -- which is why orthogonal transformations are the building block of stable algorithms",
        "A = diag(1, 1e-10): kappa = 1e10, so about 10 digits are lost",
        "kappa(A^TA) = kappa(A)^2 -- the reason the normal equations are avoided (least_squares)",
        "the Hilbert matrix H_n has kappa growing like e^{3.5n}: catastrophic by n = 12"],
  cxd={"determinant_is_not_conditioning": "A = 1e-5 * I_{10} has det = 1e-50, vanishingly small, yet kappa = 1 -- perfectly conditioned. Conversely diag(1, 1e-10) has det = 1e-10 and kappa = 1e10. The determinant is scale-sensitive and conditioning is not; the two carry entirely different information. This is the single most important practical point in the node",
       "conditioning_is_a_property_of_the_PROBLEM": "kappa bounds what ANY algorithm can achieve on this data; a backward-stable algorithm achieves it, an unstable one does worse. Conditioning and stability are different notions"},
  misuse=["using a small determinant as a near-singularity test (see above)",
          "treating a large kappa as an algorithm's fault: it is a property of the problem, and the remedy is reformulation (regularisation, scaling, a better basis), not a better solver"],
  apps=["the standard diagnostic for whether a linear system or regression is trustworthy; variance inflation factors in regression are a condition-number statement about the design matrix",
        "the reason centring and scaling predictors, and using orthogonal polynomial bases, materially improve a fit"],
  related={"contrasts_with": ["determinant_invertible_iff"], "approximates": ["linear_system"]},
  sources=["trefethen_bau", "higham_asna_2e"], status="reviewed")

N("spectral_radius", "definition", "spectral",
  "rho(A) = max_i |lambda_i| over the eigenvalues of A. It satisfies rho(A) <= ||A|| for EVERY submultiplicative norm, with equality for NORMAL A in the spectral norm, and Gelfand's formula rho(A) = lim_k ||A^k||^{1/k}.",
  parseable="rho(A) := max |lambda_i|;  rho(A) <= ||A|| for any submultiplicative norm;  rho(A) = lim_k ||A^k||^{1/k};  A normal => rho(A) = ||A||_2",
  symbols={"rho(A)": "type: nonnegative real"},
  tcn="Well-formed over an algebraically closed field (or by passing to C for a real matrix). Note rho is NOT a norm: it vanishes on nonzero nilpotent matrices and is not subadditive.",
  hyps=["eigenvalues taken over C"],
  field_scope="real_or_complex",
  proof=("rho <= ||A|| because ||Av|| = |lambda| ||v|| for an eigenvector; equality for normal A from spectral_theorem_normal, since the singular values are then the |lambda_i|. Gelfand's formula is CITED", "matrix_norms", "core", "LinAlg.spectral_radius_le_norm"),
  spec=["A normal: rho(A) = ||A||_2",
        "A^k -> 0 if and only if rho(A) < 1 -- the fundamental stability criterion for linear iterations and discrete dynamical systems",
        "A a stochastic matrix: rho(A) = 1, attained at the stationary distribution"],
  cxd={"rho_is_not_a_norm": "the nilpotent [[0,1],[0,0]] has rho = 0 while A != 0, so rho(A) = 0 does not imply A = 0. It also fails subadditivity: rho(A+B) can exceed rho(A) + rho(B)",
       "rho_does_not_bound_finite_powers": "with J = [[1,1],[0,1]], rho(J) = 1 but ||J^k||_2 grows LINEARLY in k. rho governs only the ASYMPTOTIC growth rate (Gelfand), not any individual power. Transient growth before eventual decay is a real and often decisive phenomenon in non-normal dynamics",
       "normality_for_equality": "for non-normal A the gap ||A||_2 - rho(A) can be arbitrarily large"},
  misuse=["concluding from rho(A) < 1 that ||A^k|| decreases monotonically -- it can grow substantially first (transient growth), which matters in fluid stability and in iterative solver convergence",
          "using rho as a norm in a perturbation bound"],
  apps=["convergence of stationary iterative methods (Jacobi, Gauss-Seidel) is exactly rho of the iteration matrix being < 1; stability of discrete linear dynamical systems and of Markov chain mixing"],
  related={"contrasts_with": ["matrix_norms"]},
  sources=["horn_johnson_2e", "trefethen_bau"], status="reviewed")
